import path from 'node:path';
import { pathToFileURL } from 'node:url';
const modulePath=path.resolve(path.dirname(process.execPath),'../node_modules/playwright/index.mjs');
const {chromium}=await import(pathToFileURL(modulePath).href);
const launch=chromium.launch.bind(chromium);
chromium.launch=options=>launch({...options,executablePath:'/usr/bin/chromium',args:[...(options?.args||[]),'--no-sandbox','--disable-dev-shm-usage']});
